    <article class="repo-card ${featured ? 'featured' : ''}">
      <div class="repo-title-row">
        <h3 class="repo-title">
          <a href="${escapeHtml(repo.html_url)}" target="_blank" rel="noreferrer">${escapeHtml(repo.name)}</a>
        </h3>
      </div>
