    elements.languageFilter.value = 'all';
    elements.scopeFilter.value = 'all';
    elements.sortFilter.value = 'updated-desc';
    render();
  });
}

function applyConfigCopy() {
  document.title = state.config.title || 'Public Fabric';
  elements.siteTitle.textContent = state.config.title || 'Public Fabric';
  elements.heroCopy.textContent =
    state.config.tagline ||
    'A living catalog of public repositories published by Japer Technology.';
  elements.introCopy.textContent =
    state.config.intro ||
    'This public fabric is meant to become the durable front door for every public Japer Technology repository.';
}

function updatePortfolioMetrics() {
  const repos = state.repos;
  const forkCount = repos.filter((repo) => repo.fork).length;
  const firstPartyCount = repos.length - forkCount;
  const featuredCount = repos.filter((repo) => repo.isFeatured).length;
  const experimentalCount = repos.filter((repo) => repo.status === 'experimental').length;
  const languageCount = new Set(repos.map((repo) => repo.language).filter(Boolean)).size;
  const totalStars = repos.reduce((sum, repo) => sum + (repo.stargazers_count || 0), 0);
  const latestUpdate = repos
    .map((repo) => repo.updated_at)
    .filter(Boolean)
    .sort()
    .at(-1);

  state.lastUpdated = latestUpdate;

  elements.statRepos.textContent = String(repos.length);
  elements.statFirstParty.textContent = String(firstPartyCount);
  elements.statForks.textContent = String(forkCount);
  elements.statSource.textContent = latestUpdate
    ? `${state.sourceLabel} · ${formatDate(latestUpdate)}`
    : state.sourceLabel;

  elements.snapshotFeatured.textContent = String(featuredCount);
  elements.snapshotExperimental.textContent = String(experimentalCount);
  elements.snapshotLanguages.textContent = String(languageCount);
  elements.snapshotStars.textContent = String(totalStars);

  const isLive = state.sourceLabel === 'Live GitHub API';
  elements.livePill.textContent = isLive ? 'Live GitHub data' : 'Snapshot fallback';
  elements.livePill.className = `live-pill ${isLive ? 'is-live' : 'is-fallback'}`;
}

function populateLanguageOptions() {
  const previousValue = state.filters.language;
  const languages = Array.from(
    new Set(state.repos.map((repo) => repo.language).filter(Boolean)),
  ).sort((a, b) => a.localeCompare(b));

  elements.languageFilter.innerHTML = '<option value="all">All languages</option>';
  for (const language of languages) {
    const option = document.createElement('option');
    option.value = language;
    option.textContent = language;
    elements.languageFilter.appendChild(option);
  }

  const nextValue = languages.includes(previousValue) ? previousValue : 'all';
  state.filters.language = nextValue;
  elements.languageFilter.value = nextValue;
}

function render() {
  const featuredRepos = getFeaturedRepos();
  const filteredRepos = getFilteredRepos();

  renderFeatured(featuredRepos);
  renderCatalog(filteredRepos);
  renderActiveFilters();

  const summaryParts = [`Showing ${filteredRepos.length} of ${state.repos.length} repositories`];
  if (state.filters.scope !== 'all') summaryParts.push(`scope: ${labelForScope(state.filters.scope)}`);
  if (state.filters.language !== 'all') summaryParts.push(`language: ${state.filters.language}`);
  if (state.filters.search) summaryParts.push(`search: “${state.filters.search}”`);

  elements.resultsSummary.textContent = `${summaryParts.join(' · ')}.`;
  elements.emptyState.classList.toggle('hidden', filteredRepos.length !== 0);
}

function renderFeatured(repos) {
  elements.featuredSection.classList.toggle('hidden', repos.length === 0);
  elements.featuredGrid.innerHTML = repos.map((repo) => repoCard(repo, true)).join('');
}

function renderCatalog(repos) {
  elements.repoGrid.innerHTML = repos.map((repo) => repoCard(repo, false)).join('');
}

function renderActiveFilters() {
  const chips = [];

  if (state.filters.search) {
    chips.push(filterChip(`Search: ${state.filters.search}`));
  }
  if (state.filters.language !== 'all') {
    chips.push(filterChip(`Language: ${state.filters.language}`));
  }
  if (state.filters.scope !== 'all') {
    chips.push(filterChip(`Scope: ${labelForScope(state.filters.scope)}`));
  }
  if (state.filters.sort !== DEFAULT_FILTERS.sort) {
    chips.push(filterChip(`Sort: ${labelForSort(state.filters.sort)}`));
  }

  elements.activeFilters.classList.toggle('hidden', chips.length === 0);
  elements.activeFilters.innerHTML = chips.join('');
}

function getFeaturedRepos() {
  const featuredList = state.config.featured || [];
  const featuredNames = new Set(featuredList);

  return featuredList
    .map((name) => state.repos.find((repo) => repo.name === name))
    .filter(Boolean)
    .concat(state.repos.filter((repo) => repo.isFeatured && !featuredNames.has(repo.name)));
}

function getFilteredRepos() {
  const search = state.filters.search;
  const language = state.filters.language;
  const scope = state.filters.scope;

  const filtered = state.repos.filter((repo) => {
    const matchesLanguage = language === 'all' || repo.language === language;
    const matchesScope =
      scope === 'all' ||
      (scope === 'first-party' && !repo.fork) ||
      (scope === 'forks' && repo.fork) ||
      (scope === 'featured' && repo.isFeatured) ||
      (scope === 'experimental' && repo.status === 'experimental');

    const haystack = [
      repo.name,
      repo.full_name,
      repo.summary,
      repo.description,
      repo.language,
      repo.status,
      ...(repo.topics || []),
      ...(repo.tags || []),
    ]
      .filter(Boolean)
      .join(' ')
      .toLowerCase();

    const matchesSearch = !search || haystack.includes(search);
    return matchesLanguage && matchesScope && matchesSearch;
  });

  return sortRepos(filtered, state.filters.sort);
}

function sortRepos(repos, sortMode) {
  const sorted = [...repos];

  switch (sortMode) {
    case 'stars-desc':
      return sorted.sort((a, b) => {
        const starDelta = (b.stargazers_count || 0) - (a.stargazers_count || 0);
        return starDelta || a.name.localeCompare(b.name);
      });
    case 'name-asc':
      return sorted.sort((a, b) => a.name.localeCompare(b.name));
    case 'updated-desc':
    default:
      return sorted.sort((a, b) => String(b.updated_at || '').localeCompare(String(a.updated_at || '')));
  }
}

function repoCard(repo, featuredContext) {
  const badges = [];
  if (repo.status) {
    badges.push(badge(labelForStatus(repo.status), `status-${slugify(repo.status)}`));
  }
  badges.push(badge(repo.fork ? 'Fork' : 'First-party', repo.fork ? 'kind-fork' : 'kind-original'));
  if (repo.isFeatured && repo.status !== 'featured') {
    badges.push(badge('Curated', 'status-featured'));
  }
  if (repo.archived && repo.status !== 'archived') {
    badges.push(badge('Archived', 'status-archived'));
  }
  if (featuredContext) {
    badges.push(badge('Priority view', 'priority-badge'));
  }

  const topics = [...(repo.tags || []), ...(repo.topics || [])]
    .slice(0, 8)
    .map((topic) => `<span class="topic">${escapeHtml(topic)}</span>`)
    .join('');

  const links = [
    `<a href="${escapeHtml(repo.html_url)}" target="_blank" rel="noreferrer">GitHub</a>`,
    repo.homepage
      ? `<a href="${escapeHtml(repo.homepage)}" target="_blank" rel="noreferrer">Homepage</a>`
      : '',
  ]
    .filter(Boolean)
    .join('');

  return `
    <article class="repo-card ${featuredContext ? 'featured' : ''}">
      <div class="repo-title-row">
        <div>
          <p class="repo-kicker">${escapeHtml(repo.full_name)}</p>
          <h3 class="repo-title">
            <a href="${escapeHtml(repo.html_url)}" target="_blank" rel="noreferrer">${escapeHtml(repo.name)}</a>
          </h3>
        </div>
      </div>
      <div class="badges">${badges.join('')}</div>
      <p class="repo-summary">${escapeHtml(repo.summary)}</p>
      ${topics ? `<div class="topics">${topics}</div>` : ''}
      <div class="meta-row">
        <span>${escapeHtml(repo.language || 'Unspecified language')}</span>
        <span>${repo.stargazers_count || 0} ★</span>
        <span>Updated ${escapeHtml(formatDate(repo.updated_at))}</span>
      </div>
      <div class="repo-links">${links}</div>
    </article>
  `;
}

function filterChip(text) {
  return `<span class="filter-chip">${escapeHtml(text)}</span>`;
}

function badge(text, extraClass = '') {
  return `<span class="badge ${extraClass}">${escapeHtml(text)}</span>`;
}

function normalizeRepos(repos, overrides) {
  return [...repos]
    .map((repo) => {
      const override = overrides[repo.name] || {};
      const topics = Array.from(
        new Set([...(override.tags || []), ...(repo.topics || []), ...inferTags(repo)]),
      );
      const summary = deriveSummary(repo, override);
      const isFeatured = Boolean(override.featured || (state.config.featured || []).includes(repo.name));

      return {
        ...repo,
        homepage: override.homepage || repo.homepage || '',
        description: repo.description || '',
        summary,
        status: override.status || deriveStatus(repo),
        topics,
        tags: Array.from(new Set(override.tags || [])),
        isFeatured,
      };
    })
    .sort((a, b) => {
      if (a.name === 'an-overview') return -1;
      if (b.name === 'an-overview') return 1;
      return String(b.updated_at || '').localeCompare(String(a.updated_at || ''));
    });
}

function deriveSummary(repo, override) {
  if (override.summary) return override.summary;

  const description = cleanDescription(repo.description || '');
  if (description && !looksStatusOnlyDescription(description)) {
    return description;
  }

  if (repo.name.startsWith('gmi-')) {
    const agentMatch = (repo.description || '').match(/an ai agent called\s+(.+)/i);
    if (agentMatch) {
      return `A GitHub Minimum Intelligence agent repository centered on ${agentMatch[1].trim()}.`;
    }
    return 'A GitHub Minimum Intelligence repository in the Japer Technology portfolio.';
  }

  if (repo.name.startsWith('github-') && repo.fork) {
    return 'A GitHubification fork tracked by Japer Technology while the underlying project is adapted to GitHub-native workflows.';
  }

  if (repo.name.startsWith('github-')) {
    return 'A GitHub-native repository in the Japer Technology portfolio.';
  }

  if (repo.fork) {
    return 'A public fork tracked in the Japer Technology portfolio.';
  }

  if (repo.homepage) {
    return 'A public Japer Technology repository with an associated homepage or published endpoint.';
  }

  return 'A public Japer Technology repository that still needs a more specific curated summary.';
}

function inferTags(repo) {
  const inferred = [];
  if (repo.fork) inferred.push('fork');
  if (!repo.fork) inferred.push('first-party');
  if (repo.name.startsWith('gmi-')) inferred.push('gmi');
  if (repo.name.startsWith('github-')) inferred.push('github-native');
  if (repo.name.endsWith('.github.io') || String(repo.homepage || '').includes('github.io')) inferred.push('website');
  return inferred;
}

function deriveStatus(repo) {
  if (repo.archived) return 'archived';

  const description = (repo.description || '').toLowerCase();
  if (
    description.includes('under development') ||
    description.includes('under githubification') ||
    description.includes('under dvelopment') ||
    description.includes('under dbveleopment')
  ) {
    return 'experimental';
  }

  if (repo.fork) return 'watch';
  return 'active';
}

function labelForStatus(status) {
  const labels = {
    active: 'Active',
    featured: 'Featured',
    experimental: 'Experimental',
    watch: 'Watching',
    archived: 'Archived',
  };
  return labels[status] || status;
}

function labelForScope(scope) {
  const labels = {
    all: 'All repositories',
    'first-party': 'First-party',
    forks: 'Forks only',
    featured: 'Featured only',
    experimental: 'Experimental only',
  };
  return labels[scope] || scope;
}

function labelForSort(sort) {
  const labels = {
    'updated-desc': 'Recently updated',
    'stars-desc': 'Most stars',
    'name-asc': 'Name A–Z',
  };
  return labels[sort] || sort;
}

function looksStatusOnlyDescription(description) {
  return /under\s+(githubification|development|dvelopment|dbveleopment)/i.test(description);
}

function cleanDescription(description) {
  return String(description || '').replace(/\s+/g, ' ').trim();
}

async function fetchLiveRepos(org) {
  const endpoints = [
    `https://api.github.com/orgs/${org}/repos?per_page=100&type=public&sort=updated`,
    `https://api.github.com/users/${org}/repos?per_page=100&type=public&sort=updated`,
  ];

  for (const endpoint of endpoints) {
    try {
      const repos = await fetchRepoPages(endpoint);
      if (repos.length > 0) return repos;
    } catch (error) {
      console.warn(`Failed endpoint ${endpoint}:`, error);
    }
  }

  throw new Error(`Unable to fetch repositories for ${org}`);
}

async function fetchRepoPages(baseUrl) {
  const all = [];

  for (let page = 1; page <= 10; page += 1) {
    const separator = baseUrl.includes('?') ? '&' : '?';
    const response = await fetch(`${baseUrl}${separator}page=${page}`, {
      headers: {
        Accept: 'application/vnd.github+json',
      },
    });

    if (!response.ok) {
      throw new Error(`GitHub API responded with ${response.status}`);
    }

    const pageRepos = await response.json();
    all.push(...pageRepos);
    if (pageRepos.length < 100) break;
  }

  return all.map((repo) => ({
    name: repo.name,
    full_name: repo.full_name,
    html_url: repo.html_url,
    description: repo.description,
    homepage: repo.homepage,
    language: repo.language,
    stargazers_count: repo.stargazers_count,
    fork: repo.fork,
    archived: repo.archived,
    topics: repo.topics || [],
    updated_at: repo.updated_at,
  }));
}

async function loadJson(path) {
  const response = await fetch(path);
  if (!response.ok) {
    throw new Error(`Failed to load ${path}`);
  }
  return response.json();
}

function formatDate(value) {
  if (!value) return 'unknown';
  return new Date(value).toLocaleDateString(undefined, {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
  });
}

function slugify(value) {
  return String(value).toLowerCase().replace(/[^a-z0-9]+/g, '-');
}

function escapeHtml(value) {
  return String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}
"}

arguments.content:
:root {
  color-scheme: dark;
  --bg: #08111f;
  --panel: rgba(12, 24, 43, 0.88);
  --panel-strong: rgba(16, 35, 63, 0.95);
  --panel-soft: rgba(16, 35, 63, 0.68);
  --border: rgba(150, 187, 255, 0.18);
  --border-strong: rgba(150, 187, 255, 0.32);
  --text: #ebf2ff;
  --muted: #9db3d4;
  --accent: #8dc2ff;
  --accent-strong: #4e9fff;
  --success: #66d19e;
  --success-soft: rgba(102, 209, 158, 0.14);
  --warning: #ffd26a;
  --warning-soft: rgba(255, 210, 106, 0.14);
  --danger: #ff9d9d;
  --danger-soft: rgba(255, 157, 157, 0.14);
  --featured: #d5b7ff;
  --featured-soft: rgba(213, 183, 255, 0.14);
  --shadow: 0 24px 64px rgba(0, 0, 0, 0.28);
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-height: 100vh;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background:
    radial-gradient(circle at top, rgba(78, 159, 255, 0.22), transparent 30%),
    linear-gradient(180deg, #09101d 0%, #08111f 100%);
  color: var(--text);
}

body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.03) 1px, transparent 1px);
  background-size: 24px 24px;
  mask-image: linear-gradient(180deg, rgba(0, 0, 0, 0.75), transparent 92%);
}

::selection {
  background: rgba(141, 194, 255, 0.32);
}

.shell {
  width: min(1180px, calc(100% - 2rem));
  margin: 0 auto;
  padding: 2rem 0 3rem;
}

.hero,
.panel,
.footer {
  position: relative;
  z-index: 1;
}

.hero {
  padding: 3rem;
  border: 1px solid var(--border);
  border-radius: 30px;
  background: linear-gradient(180deg, rgba(16, 35, 63, 0.96), rgba(10, 20, 37, 0.96));
  box-shadow: var(--shadow);
}

.hero-topline {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 0.75rem;
  align-items: center;
}

.eyebrow {
  margin: 0;
  font-size: 0.85rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--accent);
}

.live-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  min-height: 2rem;
  padding: 0.35rem 0.8rem;
  border-radius: 999px;
  border: 1px solid var(--border);
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--text);
  background: rgba(255, 255, 255, 0.05);
}

.live-pill::before {
  content: "";
  width: 0.55rem;
  height: 0.55rem;
  border-radius: 50%;
  background: currentColor;
  opacity: 0.85;
}

.live-pill.is-live {
  color: var(--success);
  border-color: rgba(102, 209, 158, 0.28);
  background: var(--success-soft);
}

.live-pill.is-fallback {
  color: var(--warning);
  border-color: rgba(255, 210, 106, 0.26);
  background: var(--warning-soft);
}

h1,
h2,
h3,
p,
dl {
  margin-top: 0;
}

h1 {
  margin: 1rem 0;
  font-size: clamp(2.35rem, 4vw, 4.25rem);
  line-height: 1.02;
  letter-spacing: -0.03em;
}

h2 {
  font-size: clamp(1.55rem, 2.3vw, 2rem);
  margin-bottom: 0.6rem;
}

h3 {
  margin-bottom: 0.4rem;
}

.hero-copy,
#intro-copy,
.section-heading p,
.repo-summary,
.results-summary,
.footer,
.callout p,
.meta-row,
.repo-links,
.field span,
.empty-state p,
.repo-kicker,
.snapshot-copy {
  color: var(--muted);
}

.hero-copy,
#intro-copy {
  font-size: 1.08rem;
  max-width: 70ch;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.9rem;
  margin: 1.75rem 0 2rem;
}

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 2.8rem;
  padding: 0.72rem 1.1rem;
  border-radius: 999px;
  border: 1px solid var(--border);
  text-decoration: none;
  font-weight: 700;
  font: inherit;
  cursor: pointer;
  transition:
    transform 160ms ease,
    border-color 160ms ease,
    background 160ms ease,
    box-shadow 160ms ease;
}

.button:hover,
.button:focus-visible {
  transform: translateY(-1px);
  border-color: var(--border-strong);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.18);
}

.button.primary {
  color: #04101d;
  background: linear-gradient(135deg, var(--accent), #d2e9ff);
}

.button.secondary,
.button.tertiary {
  color: var(--text);
  background: rgba(255, 255, 255, 0.04);
}

.stats {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1rem;
  margin-bottom: 0;
}

.stat-card,
.snapshot-card {
  margin: 0;
  padding: 1rem 1.1rem;
  border-radius: 20px;
  border: 1px solid var(--border);
  background: rgba(255, 255, 255, 0.03);
}

.stat-card dt {
  margin-bottom: 0.35rem;
  font-size: 0.85rem;
  color: var(--muted);
}

.stat-card dd {
  margin: 0;
  font-size: 1.4rem;
  font-weight: 800;
}

.panel {
  margin-top: 1.5rem;
  padding: 1.75rem;
  border-radius: 24px;
  border: 1px solid var(--border);
  background: var(--panel);
  box-shadow: var(--shadow);
}

.intro-panel {
  display: grid;
  grid-template-columns: 1.45fr 1fr;
  gap: 1.25rem;
  align-items: stretch;
}

.intro-copy-block {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 1rem;
}

.legend-row,
.badges,
.topics,
.repo-links,
.active-filters {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.callout {
  padding: 1rem 1.1rem;
  border-radius: 18px;
  border: 1px solid rgba(102, 209, 158, 0.25);
  background: rgba(102, 209, 158, 0.08);
}

.callout strong {
  display: block;
  margin-bottom: 0.5rem;
}

.section-heading {
  margin-bottom: 1.25rem;
}

.snapshot-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1rem;
}

.snapshot-card {
  min-height: 100%;
  background: linear-gradient(180deg, rgba(16, 35, 63, 0.86), rgba(8, 17, 31, 0.92));
}

.snapshot-card h3 {
  font-size: 1rem;
}

.snapshot-value {
  margin: 0 0 0.35rem;
  font-size: clamp(1.7rem, 3vw, 2.5rem);
  font-weight: 800;
}

.snapshot-copy {
  margin-bottom: 0;
  line-height: 1.55;
}

.filters {
  display: grid;
  grid-template-columns: minmax(0, 2fr) repeat(3, minmax(180px, 1fr)) 160px;
  gap: 1rem;
  margin-bottom: 1rem;
  align-items: end;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

.field-search {
  min-width: 0;
}

.action-field {
  align-self: end;
}

input,
select {
  width: 100%;
  min-height: 2.9rem;
  padding: 0.75rem 0.9rem;
  border-radius: 14px;
  border: 1px solid var(--border);
  background: rgba(5, 11, 20, 0.9);
  color: var(--text);
  font: inherit;
}

input::placeholder {
  color: rgba(157, 179, 212, 0.82);
}

input:focus,
select:focus,
.button:focus-visible {
  outline: 2px solid rgba(141, 194, 255, 0.32);
  outline-offset: 2px;
}

.results-summary {
  margin-bottom: 0.85rem;
}

.active-filters {
  margin-bottom: 1rem;
}

.filter-chip,
.badge,
.topic {
  display: inline-flex;
  align-items: center;
  min-height: 1.9rem;
  padding: 0.22rem 0.58rem;
  border-radius: 999px;
  font-size: 0.78rem;
  font-weight: 700;
}

.filter-chip,
.badge {
  color: var(--text);
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.08);
}

