{"path":".github-minimum-intelligence/public-fabric/styles.css","content":":root {
  color-scheme: dark;
  --bg: #08111f;
  --panel: rgba(12, 24, 43, 0.88);
  --panel-strong: rgba(16, 35, 63, 0.95);
  --panel-soft: rgba(16, 35, 63, 0.68);
  --border: rgba(150, 187, 255, 0.18);
  --border-strong: rgba(150, 187, 255, 0.32);
  --text: #ebf2ff;
  --muted: #9db3d4;
  --accent: #8dc2ff;
  --accent-strong: #4e9fff;
  --success: #66d19e;
  --success-soft: rgba(102, 209, 158, 0.14);
  --warning: #ffd26a;
  --warning-soft: rgba(255, 210, 106, 0.14);
  --danger: #ff9d9d;
  --danger-soft: rgba(255, 157, 157, 0.14);
  --featured: #d5b7ff;
  --featured-soft: rgba(213, 183, 255, 0.14);
  --shadow: 0 24px 64px rgba(0, 0, 0, 0.28);
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-height: 100vh;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background:
    radial-gradient(circle at top, rgba(78, 159, 255, 0.22), transparent 30%),
    linear-gradient(180deg, #09101d 0%, #08111f 100%);
  color: var(--text);
}

body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.03) 1px, transparent 1px);
  background-size: 24px 24px;
  mask-image: linear-gradient(180deg, rgba(0, 0, 0, 0.75), transparent 92%);
}

::selection {
  background: rgba(141, 194, 255, 0.32);
}

.shell {
  width: min(1180px, calc(100% - 2rem));
  margin: 0 auto;
  padding: 2rem 0 3rem;
}

.hero,
.panel,
.footer {
  position: relative;
  z-index: 1;
}

.hero {
  padding: 3rem;
  border: 1px solid var(--border);
  border-radius: 30px;
  background: linear-gradient(180deg, rgba(16, 35, 63, 0.96), rgba(10, 20, 37, 0.96));
  box-shadow: var(--shadow);
}

.hero-topline {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 0.75rem;
  align-items: center;
}

.eyebrow {
  margin: 0;
  font-size: 0.85rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--accent);
}

.live-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  min-height: 2rem;
  padding: 0.35rem 0.8rem;
  border-radius: 999px;
  border: 1px solid var(--border);
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--text);
  background: rgba(255, 255, 255, 0.05);
}

.live-pill::before {
  content: "";
  width: 0.55rem;
  height: 0.55rem;
  border-radius: 50%;
  background: currentColor;
  opacity: 0.85;
}

.live-pill.is-live {
  color: var(--success);
  border-color: rgba(102, 209, 158, 0.28);
  background: var(--success-soft);
}

.live-pill.is-fallback {
  color: var(--warning);
  border-color: rgba(255, 210, 106, 0.26);
  background: var(--warning-soft);
}

h1,
h2,
h3,
p,
dl {
  margin-top: 0;
}

h1 {
  margin: 1rem 0;
  font-size: clamp(2.35rem, 4vw, 4.25rem);
  line-height: 1.02;
  letter-spacing: -0.03em;
}

h2 {
  font-size: clamp(1.55rem, 2.3vw, 2rem);
  margin-bottom: 0.6rem;
}

h3 {
  margin-bottom: 0.4rem;
}

.hero-copy,
#intro-copy,
.section-heading p,
.repo-summary,
.results-summary,
.footer,
.callout p,
.meta-row,
.repo-links,
.field span,
