}

.snapshot-value {
  margin: 0 0 0.35rem;
  font-size: clamp(1.7rem, 3vw, 2.5rem);
  font-weight: 800;
}

.snapshot-copy {
  margin-bottom: 0;
  line-height: 1.55;
}

.filters {
  display: grid;
  grid-template-columns: minmax(0, 2fr) repeat(3, minmax(180px, 1fr)) 160px;
  gap: 1rem;
  margin-bottom: 1rem;
  align-items: end;
