.field {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

.field-search {
  min-width: 0;
}

.action-field {
  align-self: end;
}

input,
select {
  width: 100%;
  min-height: 2.9rem;
  padding: 0.75rem 0.9rem;
  border-radius: 14px;
  border: 1px solid var(--border);
  background: rgba(5, 11, 20, 0.9);
